rawInput.command:
$ErrorActionPreference = 'Stop'
$repo = 'C:\Users\magicvr\Documents\Code\goal-governance'
$gov = Join-Path $repo 'docs'
function Get-Frontmatter([string]$path) {
  $text = Get-Content -LiteralPath $path -Raw -Encoding UTF8
  if ($text -notmatch '(?s)\A---\r?\n(.*?)\r?\n---') { return $null }
  return $Matches[1]
}
function Test-Reparse([string]$path, [string]$repoRoot) {
  $item = Get-Item -LiteralPath $path -Force
  $resolved = (Resolve-Path -LiteralPath $path).Path
  $repoR = (Resolve-Path -LiteralPath $repoRoot).Path
  $inside = $resolved.StartsWith($repoR, [System.StringComparison]::OrdinalIgnoreCase)
  [pscustomobject]@{
    path = $path
    linkType = $item.LinkType
    attributes = [string]$item.Attributes
    resolved = $resolved
    inside = $inside
  }
}
Write-Output '=== CANONICAL ==='
$canon = Get-ChildItem -LiteralPath (Join-Path $gov 'workspaces') -Directory -ErrorAction SilentlyContinue |
  Where-Object { $_.Name -like 'workspace-*' }
if (-not $canon) { Write-Output 'NONE' }
foreach ($d in $canon) {
  $wm = Join-Path $d.FullName 'workspace.md'
  $has = Test-Path -LiteralPath $wm
  Write-Output ("DIR {0} workspace.md={1}" -f $d.Name, $has)
  $rp = Test-Reparse $d.FullName $repo
  Write-Output ("  link={0} inside={1} resolved={2}" -f $rp.linkType, $rp.inside, $rp.resolved)
}
Write-Output '=== OLD DIRECT ==='
$oldParent = $gov
$old = Get-ChildItem -LiteralPath $oldParent -Directory -ErrorAction SilentlyContinue |
  Where-Object { $_.Name -like 'workspace-*' -and $_.Name -notlike 'workspaces' }
if (-not $old) { Write-Output 'NONE' } else { $old | ForEach-Object { Write-Output $_.FullName } }
Write-Output '=== GOALS LEGACY ==='
Write-Output ("docs/goals exists=" + (Test-Path -LiteralPath (Join-Path $gov 'goals')))
Write-Output '=== WORKSPACE FM ==='
foreach ($d in $canon) {
  $wm = Join-Path $d.FullName 'workspace.md'
  if (-not (Test-Path -LiteralPath $wm)) { continue }
  $fm = Get-Frontmatter $wm
  Write-Output "---- $($d.Name) ----"
  Write-Output $fm
}

