rawInput.command:
$ErrorActionPreference = 'Stop'
$repo = 'C:\Users\magicvr\Documents\Code\goal-governance'
$ws = Join-Path $repo 'docs\workspaces\workspace-002-methodology-skills-feedback'
function Get-Frontmatter([string]$path) {
  $text = Get-Content -LiteralPath $path -Raw -Encoding UTF8
  if ($text -notmatch '(?s)\A---\r?\n(.*?)\r?\n---') { throw "NO_FM $path" }
  return $Matches[1]
}
function Show-Link([string]$path) {
  $item = Get-Item -LiteralPath $path -Force
  $resolved = (Resolve-Path -LiteralPath $path).Path
  $inside = $resolved.StartsWith((Resolve-Path $repo).Path, [System.StringComparison]::OrdinalIgnoreCase)
  Write-Output ("LINK path={0} linkType='{1}' inside={2}" -f $item.Name, $item.LinkType, $inside)
}
Write-Output '=== CHARTER FM ==='
$charter = Join-Path $repo 'docs\vision\charter.md'
Show-Link $charter
Write-Output (Get-Frontmatter $charter)
Write-Output '=== VP-002 FILES ==='
Get-ChildItem -LiteralPath (Join-Path $repo 'docs\vision\plans') -Filter 'VP-002*' | ForEach-Object { Write-Output $_.Name }
Write-Output '=== ALL VP BIND COUNTS FROM WS FM (id + primary_plan + vision_role only already known) ==='
Write-Output '=== ROOT META FM ==='
$rootMeta = Join-Path $ws 'GOAL-001-methodology-skills-feedback-evolution\00-meta.md'
Show-Link (Split-Path $rootMeta)
Write-Output (Get-Frontmatter $rootMeta)
Write-Output '=== GOAL-019 DIRS ==='
Get-ChildItem -LiteralPath $ws -Directory | Where-Object { $_.Name -match '^GOAL-019(-|$)' } | ForEach-Object {
  Show-Link $_.FullName
  $meta = Join-Path $_.FullName '00-meta.md'
  Write-Output ("meta_exists=" + (Test-Path -LiteralPath $meta))
  if (Test-Path -LiteralPath $meta) {
    Write-Output '--- META FM ---'
    Write-Output (Get-Frontmatter $meta)
  }
}
Write-Output '=== GOAL TREE IDENTITY LINES FOR 019 / ROOT ==='
$tree = Join-Path $ws 'goal-tree.md'
Show-Link $tree
$lines = Get-Content -LiteralPath $tree -Encoding UTF8
for ($i=0; $i -lt $lines.Count; $i++) {
  $l = $lines[$i]
  if ($l -match 'GOAL-019' -or $l -match 'GOAL-001-methodology') {
    Write-Output ("{0}: {1}" -f ($i+1), $l)
  }
}

