import json
p=r'docs/workspaces/workspace-002-methodology-skills-feedback/GOAL-019-independent-audit-lifecycle/attachments/s4-formal/release-evidence.json'
d=json.load(open(p,encoding='utf-8'))
print('format', d.get('format'), d.get('formatVersion'), d.get('schemaId'))
print('generatedAt', d.get('generatedAt'))
print('protocol', d.get('protocol'))
print('releaseStatus', d.get('releaseStatus'))
print('checksPassed', d.get('checksPassed'))
src=d.get('source') or {}
print('source_keys', list(src)[:30])
for k,v in src.items():
    if not isinstance(v,(dict,list)):
        print('source.'+k, v)
wt=d.get('workingTree') or {}
print('workingTree', {k:v for k,v in wt.items() if not isinstance(v,(dict,list))})
cr=d.get('compatibilityReport') or {}
print('compat_keys', list(cr)[:20] if isinstance(cr, dict) else type(cr))
if isinstance(cr, dict):
    for k,v in cr.items():
        if not isinstance(v,(dict,list)):
            print('compat.'+k, v)
checks=d.get('checks')
print('checks_type', type(checks).__name__, 'len', len(checks) if hasattr(checks,'__len__') else None)
if isinstance(checks, dict):
    print('check_keys', list(checks)[:40])
    for k,v in checks.items():
        if not isinstance(v,(dict,list)):
            print('checks.'+k, v)
        elif isinstance(v, dict):
            flat={kk:vv for kk,vv in v.items() if not isinstance(vv,(dict,list))}
            print('checks.'+k, flat)
elif isinstance(checks, list):
    print('nchecks', len(checks))
    for c in checks:
        if isinstance(c, dict):
            print({k:c.get(k) for k in ('id','name','status','ok','passed','verdict') if k in c})
dig=d.get('digests')
print('digests_type', type(dig).__name__)
if isinstance(dig, dict):
    print('digest_keys', list(dig)[:30])
    for k,v in dig.items():
        if not isinstance(v,(dict,list)):
            print('digest.'+k, v)
"@
